export default function f({ date }) {
  const day = date || new Date().toISOString().slice(0, 10);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(day) || Number.isNaN(Date.parse(day + "T00:00:00Z")))
    throw Error("Enter a UTC date YYYY-MM-DD");
  const after = day + "T00:00:00Z",
    before = new Date(Date.parse(after) + 86400000).toISOString();
  return {
    day,
    body: {
      query:
        "query DailyPosts($after: DateTime!, $before: DateTime!) { posts(first: 10, postedAfter: $after, postedBefore: $before) { edges { node { id name tagline description website } } } }",
      variables: { after, before },
    },
  };
}

