export default async function f({ body, day, previous, namespace, acknowledge, resolution }, ctx) {
  if (body?.errors?.length || !Array.isArray(body?.data?.posts?.edges))
    throw Error("Invalid Product Hunt response");
  if (!/^[\w-]{1,80}$/.test(namespace)) throw Error("Configure a sheet namespace");
  const edges = body.data.posts.edges,
    i = previous?.index ?? 0;
  if (i >= edges.length)
    return {
      namespace,
      state: { index: i },
      more: false,
      id: "-",
      name: "",
      tagline: "",
      description: "",
      website: "https://www.producthunt.com/",
    };
  const p = edges[i]?.node;
  if (!p?.id || !p.name || !p.website) throw Error("Invalid post data");
  let u;
  try {
    u = new URL(p.website);
  } catch {
    throw Error("Invalid product website");
  }
  if (
    u.protocol !== "https:" ||
    u.username ||
    u.password ||
    !/(^|\.)producthunt\.com$/i.test(u.hostname)
  )
    throw Error("Expected Product Hunt website redirect");
  const key = "producthunt:" + namespace + ":" + day + ":" + p.id,
    s = await ctx.state.get(key);
  if (s?.phase === "pending") {
    if (acknowledge !== key || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect pending sheet write " + key);
    await ctx.state.set(key, resolution === "confirmed" ? { phase: "done" } : null);
    return f({ body, day, previous, namespace, acknowledge: "", resolution: "" }, ctx);
  }
  if (s?.phase === "done")
    return f({ body, day, previous: { index: i + 1 }, namespace, acknowledge, resolution }, ctx);
  return {
    namespace,
    state: { index: i },
    more: true,
    id: String(p.id),
    name: String(p.name),
    tagline: String(p.tagline ?? ""),
    description: String(p.description ?? ""),
    website: u.href,
  };
}

