export default async function f(
  { day, id, name, tagline, description, website, status, headers, rows, namespace },
  ctx,
) {
  if (status < 200 || status >= 400) throw Error("Product redirect request failed");
  const location = headers.location;
  let u;
  try {
    u = new URL(location || website, website);
  } catch {
    throw Error("Invalid redirect URL");
  }
  if (u.protocol !== "https:" && u.protocol !== "http:") throw Error("Invalid redirect protocol");
  u.searchParams.delete("ref");
  const next_url = u.href;
  if (!Array.isArray(rows) || !Array.isArray(rows[0])) throw Error("Create a header row");
  const h = rows[0],
    cols = ["id", "name", "tagline", "description", "next_url"];
  if (cols.some((x) => h.filter((c) => c === x).length !== 1))
    throw Error("Sheet headers must include each required field once");
  const matches = rows
    .slice(1)
    .map((r, i) => (r[h.indexOf("id")] === id ? i + 2 : 0))
    .filter(Boolean);
  if (matches.length > 1) throw Error("Duplicate post ID");
  const data = { id, name, tagline, description, next_url },
    row = h.map((k, i) =>
      Object.hasOwn(data, k) ? data[k] : matches.length ? (rows[matches[0] - 1]?.[i] ?? "") : "",
    ),
    key = "producthunt:" + namespace + ":" + day + ":" + id;
  if (await ctx.state.get(key)) throw Error("Inspect existing checkpoint");
  await ctx.state.set(key, { phase: "pending" });
  return {
    key,
    phase: matches.length ? "update" : "append",
    range: matches.length ? "'Products'!A" + matches[0] : "'Products'!A:ZZ",
    values: [row],
  };
}

