export default async function f({ key, n }, ctx) {
  if (n !== 1) throw Error("Inspect sheet write");
  const s = await ctx.state.get(key);
  if (s?.phase !== "pending") throw Error("Missing pending checkpoint");
  await ctx.state.set(key, { phase: "done" });
  return { ok: true };
}
